<script setup lang="ts">
import { onMounted,ref } from 'vue'
import { Cloud,RefreshCw,Save } from 'lucide-vue-next'
import { useAuthStore } from '@/stores/useAuthStore'
const auth=useAuthStore(); const config=ref<any>({configured:false}); const provider=ref<'aliyun'|'tencent'|'aws'|'huawei'>('aliyun'); const instances=ref<any[]>([]); const showForm=ref(false); const busy=ref(false); const message=ref(''); const error=ref('')
const form=ref({provider:'aliyun' as 'aliyun'|'tencent'|'aws'|'huawei',endpoint:'ecs.aliyuncs.com',regionId:'cn-hangzhou',projectId:'',accessKeyId:'',accessKeySecret:'',insecure:true,enabled:true})
function endpointFor(value:'aliyun'|'tencent'|'aws'|'huawei'){return value==='tencent'?'cvm.tencentcloudapi.com':value==='aws'?'ec2.us-east-1.amazonaws.com':value==='huawei'?'ecs.cn-north-4.myhuaweicloud.com':'ecs.aliyuncs.com'}
function regionFor(value:'aliyun'|'tencent'|'aws'|'huawei'){return value==='tencent'?'ap-guangzhou':value==='aws'?'us-east-1':value==='huawei'?'cn-north-4':'cn-hangzhou'}
function selectProvider(){form.value.provider=provider.value;form.value.endpoint=endpointFor(provider.value);form.value.regionId=regionFor(provider.value);form.value.projectId='';config.value={configured:false};instances.value=[];message.value='';error.value=''}
function cloudBase(){return provider.value==='tencent'?'/api/v1/cmdb/cloud-tencent':provider.value==='aws'?'/api/v1/cmdb/cloud-aws':provider.value==='huawei'?'/api/v1/cmdb/cloud-huawei':'/api/v1/cmdb/cloud'}
function payload(){return {...form.value,secretId:form.value.accessKeyId,secretKey:form.value.accessKeySecret}}
const headers=()=>({Authorization:`Bearer ${auth.token}`,'Content-Type':'application/json'})
async function api(path:string,init?:RequestInit){const r=await fetch(path,{...init,headers:headers()});const b=await r.json().catch(()=>({}));if(!r.ok)throw new Error(b.message||'请求失败');return b}
async function load(){busy.value=true;error.value='';form.value.provider=provider.value;try{config.value=await api(cloudBase()+'/config');if(config.value.configured){const d=await api(cloudBase()+'/inventory');instances.value=d.instances||[];form.value.endpoint=d.endpoint||config.value.endpoint||endpointFor(provider.value);form.value.regionId=d.regionId||config.value.regionId||regionFor(provider.value);form.value.projectId=config.value.projectId||'';form.value.accessKeyId=config.value.accessKeyId||''}}catch(e){error.value=e instanceof Error?e.message:'加载失败'}finally{busy.value=false}}
async function save(){busy.value=true;try{config.value=await api(cloudBase()+'/config',{method:'PUT',body:JSON.stringify(payload())});message.value='配置已保存';await load()}catch(e){error.value=e instanceof Error?e.message:'保存失败'}finally{busy.value=false}}
async function test(){busy.value=true;try{await api(cloudBase()+'/config/test',{method:'POST',body:JSON.stringify(payload())});message.value='连接测试通过'}catch(e){error.value=e instanceof Error?e.message:'连接失败'}finally{busy.value=false}}
async function sync(){busy.value=true;try{const r=await api(cloudBase()+'/sync',{method:'POST'});message.value=`已同步 ${r.instances} 台云主机`;await load()}catch(e){error.value=e instanceof Error?e.message:'同步失败'}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="cloud-panel"><header><div><span>CLOUD RESOURCE SYNC</span><h2>云资源同步</h2><p>阿里云 ECS、腾讯云 CVM、AWS EC2、华为云 ECS 接入，凭据保存到 Vault。</p></div><div><button @click="showForm=!showForm">配置连接</button><button :disabled="busy" @click="load"><RefreshCw/>刷新</button><button class="primary" :disabled="busy||!config.configured" @click="sync"><Cloud/>同步</button></div></header><p v-if="error" class="error">{{error}}</p><p v-if="message" class="message">{{message}}</p><form v-if="showForm" @submit.prevent="save"><label>云厂商<select v-model="provider" @change="selectProvider"><option value="aliyun">阿里云 ECS</option><option value="tencent">腾讯云 CVM</option><option value="aws">AWS EC2</option><option value="huawei">华为云 ECS</option></select></label><label>接入点<input v-model="form.endpoint"></label><label>地域<input v-model="form.regionId"></label><label>项目 ID（华为云）<input v-model="form.projectId"></label><label>SecretId / AccessKey ID<input v-model="form.accessKeyId"></label><label>SecretKey / AccessKey Secret<input v-model="form.accessKeySecret" type="password"></label><label><input v-model="form.insecure" type="checkbox">跳过TLS校验</label><label><input v-model="form.enabled" type="checkbox">启用同步</label><button type="button" @click="test">测试连接</button><button class="primary" type="submit"><Save/>保存</button></form><div v-if="config.configured" class="instances"><article v-for="i in instances" :key="i.InstanceID"><div><strong>{{i.Name||i.InstanceID}}</strong><span>{{i.InstanceID}} · {{i.ZoneID}}</span></div><div><b>{{i.Status}}</b><span>{{i.PublicIP||i.PrivateIP}} · {{i.InstanceType}}</span></div></article></div></section></template>
<style scoped>
.cloud-panel{padding:18px;border:1px solid #173b55;border-radius:12px;background:#071925}.cloud-panel>header{display:flex;justify-content:space-between;gap:12px}.cloud-panel header span{color:#22d3ee;font:10px monospace;letter-spacing:.12em}.cloud-panel h2{margin:5px 0}.cloud-panel p{margin:0;color:#7894a8;font-size:11px}.cloud-panel header>div:last-child{display:flex;gap:8px}.cloud-panel button{display:inline-flex;align-items:center;gap:6px;padding:8px 11px;border:1px solid #23455f;background:#0b263b;color:#bdd8e9;border-radius:6px}.cloud-panel button.primary{background:#087b9e}.cloud-panel form{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:14px;padding:14px;border:1px solid #246c98;background:#061620}.cloud-panel label{display:grid;gap:5px;color:#7894a8;font-size:10px}.cloud-panel label:has(input[type=checkbox]){display:flex;align-items:center}.cloud-panel input{height:34px;border:1px solid #28536c;background:#031525;color:#d5edf8;padding:0 8px}.cloud-panel .error{color:#ff9cad}.cloud-panel .message{color:#a5f3fc}.instances{display:grid;gap:8px;margin-top:12px}.instances article{display:flex;justify-content:space-between;padding:11px;border:1px solid #16445c;background:#061620}.instances strong,.instances span{display:block}.instances span{color:#6f91a5;font-size:10px}.instances b{color:#2dd4bf}
</style>
